import { createClient } from 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm';

const cfg = window.EVALORA_CONFIG || {};
const configured = /^https:\/\/.+\.supabase\.co$/.test(cfg.SUPABASE_URL || '') && (cfg.SUPABASE_ANON_KEY || '').length > 30 && !String(cfg.SUPABASE_URL).includes('YOUR-PROJECT') && !String(cfg.SUPABASE_ANON_KEY).includes('YOUR_');
const supabase = configured ? createClient(cfg.SUPABASE_URL, cfg.SUPABASE_ANON_KEY) : null;
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const state = { user:null, profile:null, page:'dashboard', courses:[], settings:null, feedback:[], people:[], announcements:[], filters:{} };
const pageNames = {dashboard:'Overview','give-feedback':'Submit feedback','my-feedback':'My submissions',courses:'Courses',faculty:'Faculty insights',analytics:'Analytics',manage:'Portal management',people:'People & access',settings:'Portal settings'};
const esc = v => String(v ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials = name => String(name||'').trim().split(/\s+/).slice(0,2).map(s=>s[0]||'').join('').toUpperCase() || 'U';
const date = v => v ? new Intl.DateTimeFormat(undefined,{year:'numeric',month:'short',day:'numeric'}).format(new Date(v)) : '—';
const avg = nums => nums.length ? nums.reduce((a,b)=>a+b,0)/nums.length : null;
const fmt = n => n == null ? '—' : Number(n).toFixed(1);
function toast(message, kind='success'){const el=document.createElement('div');el.className=`toast ${kind}`;el.textContent=message;$('#toastRegion').append(el);setTimeout(()=>el.remove(),4000)}
function fail(message){toast(message,'error')}
function requireClient(){if(!configured){toast('Connect Supabase first: add your project URL and anon key in config.js.','error');return false}return true}
function setMessage(msg){const el=$('#loginMessage');if(el)el.textContent=msg||''}
function showLogin(){ $('#loginScreen').classList.remove('hidden');$('#appShell').classList.add('hidden'); }
function showApp(){ $('#loginScreen').classList.add('hidden');$('#appShell').classList.remove('hidden'); }
function roleLabel(role){return ({student:'Student account',faculty:'Faculty account',admin:'Portal administrator'})[role]||'Account'}
function can(page){const roles={faculty:['faculty','admin'],analytics:['faculty','admin'],manage:['admin'],people:['admin'],settings:['admin'],'give-feedback':['student'],'my-feedback':['student']};return !roles[page]||roles[page].includes(state.profile?.role)}
function updateUser(){const p=state.profile||{};$('#userName').textContent=p.full_name||state.user?.email||'Account';$('#userRole').textContent=roleLabel(p.role);$('#userAvatar').textContent=initials(p.full_name||state.user?.email);$('#connectionLabel').textContent='Live data';}
async function loadProfile(user){const {data,error}=await supabase.from('profiles').select('*').eq('id',user.id).single();if(error)throw error;if(!data.is_active)throw new Error('This account has been disabled. Contact your portal administrator.');state.user=user;state.profile=data;updateUser()}
async function logAction(action, entity_type, entity_id=null, details={}){try{await supabase.from('audit_logs').insert({actor_id:state.user.id,action,entity_type,entity_id:entity_id?String(entity_id):null,details})}catch(e){console.warn('Audit log not saved',e.message)}}
async function refreshCommon(){const [cr,settings,ann]=await Promise.all([supabase.from('courses').select('*,faculty:profiles!courses_faculty_id_fkey(full_name,email)').order('created_at',{ascending:false}),supabase.from('portal_settings').select('*').eq('id',true).maybeSingle(),supabase.from('announcements').select('*').eq('is_published',true).order('created_at',{ascending:false})]);if(cr.error)throw cr.error;state.courses=cr.data||[];state.settings=settings.data||null;state.announcements=ann.data||[]}
async function navigate(page){if(!can(page)){fail('You do not have permission to open this section.');return}state.page=page;$('#breadcrumbPage').textContent=pageNames[page]||'Overview';$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#sidebar').classList.remove('open');await renderPage()}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><span class="eyebrow accent">EVALORA WORKSPACE</span><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`}
function stat(label,value,note,icon='◈'){return `<article class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></article>`}
function empty(title,desc,action=''){return `<div class="empty-state"><div class="empty-icon">⌁</div><h3>${title}</h3><p>${desc}</p>${action}</div>`}
function courseTitle(id){return state.courses.find(c=>c.id===id)?.title||'Course unavailable'}
async function renderPage(){const root=$('#pageContent');root.innerHTML='<div class="loading-state"><div class="spinner"></div><p>Loading live institutional data…</p></div>';try{await refreshCommon();let html='';switch(state.page){case'dashboard':html=await dashboardPage();break;case'courses':html=await coursesPage();break;case'give-feedback':html=await feedbackFormPage();break;case'my-feedback':html=await myFeedbackPage();break;case'faculty':html=await facultyPage();break;case'analytics':html=await analyticsPage();break;case'manage':html=await managePage();break;case'people':html=await peoplePage();break;case'settings':html=await settingsPage();break;default:html=await dashboardPage()}root.innerHTML=html;bindPageActions()}catch(e){console.error(e);root.innerHTML=`${heading('Unable to load this section','The portal could not retrieve current data.')}<div class="error-panel"><strong>Data request failed</strong><p>${esc(e.message||'Check your connection and database policies.')}</p><button class="secondary-btn" data-action="retry">Try again</button></div>`}}
async function dashboardPage(){const role=state.profile.role;const isAdmin=role==='admin';let ownFeedback=[],enrolled=[],allFeedback=[];if(role==='student'){const r=await supabase.from('feedback').select('*,courses(title,code)').eq('student_id',state.user.id).order('created_at',{ascending:false});if(r.error)throw r.error;ownFeedback=r.data||[];const e=await supabase.from('enrollments').select('course_id,courses(id,title,code,feedback_open,is_published)').eq('student_id',state.user.id);if(e.error)throw e.error;enrolled=(e.data||[]).map(x=>x.courses).filter(Boolean)}else{const r=await supabase.from('feedback').select('id,teaching_quality,course_content,engagement,assessment,created_at,course_id');if(r.error)throw r.error;allFeedback=r.data||[]}
let body='';if(isAdmin){const [pr,fr,er]=await Promise.all([supabase.from('profiles').select('id',{count:'exact',head:true}),supabase.from('feedback').select('id',{count:'exact',head:true}),supabase.from('courses').select('id',{count:'exact',head:true})]);body=`<div class="stats-grid">${stat('Registered people',pr.count??'—','Live account records','♧')}${stat('Courses',er.count??'—','Across the institution','▣')}${stat('Feedback submissions',fr.count??'—','Actual submissions only','✎')}${stat('Published courses',state.courses.filter(c=>c.is_published).length,'Visible to students','↗')}</div><section class="panel"><div class="panel-head"><div><h2>Administrator workspace</h2><p>Manage academic records, access, feedback windows, and portal settings.</p></div><span class="status-pill">Admin access</span></div><div class="quick-grid"><button class="quick-action" data-page="manage"><span>⚙</span><strong>Manage portal</strong><small>Courses, announcements and controls</small></button><button class="quick-action" data-page="people"><span>♧</span><strong>People & access</strong><small>Roles, departments and status</small></button><button class="quick-action" data-page="analytics"><span>▥</span><strong>View analytics</strong><small>Ratings and response volume</small></button><button class="quick-action" data-page="settings"><span>☷</span><strong>Portal settings</strong><small>Institution and feedback policy</small></button></div></section>`}
else if(role==='student'){const pending=enrolled.filter(c=>c.feedback_open&&!ownFeedback.some(f=>f.course_id===c.id));body=`<div class="welcome-strip"><div><span class="eyebrow">YOUR VOICE COUNTS</span><h2>${esc(state.settings?.institution_name||'Your institution')}</h2><p>${esc(state.settings?.welcome_message||'Your feedback helps improve the learning experience.')}</p></div><div class="welcome-mark">e</div></div><div class="stats-grid">${stat('Enrolled courses',enrolled.length,'Your current course list','▣')}${stat('Submitted feedback',ownFeedback.length,'Your recorded responses','✎')}${stat('Awaiting your feedback',pending.length,'Feedback windows currently open','◷')}</div><section class="panel"><div class="panel-head"><div><h2>Courses needing your feedback</h2><p>Only courses assigned to your account are shown.</p></div><button class="text-btn" data-page="give-feedback">Submit feedback →</button></div>${pending.length?`<div class="course-list">${pending.map(c=>`<div class="course-row"><div class="course-badge">${esc(c.code?.slice(0,2)||'CO')}</div><div class="course-info"><strong>${esc(c.title)}</strong><span>${esc(c.code)}</span></div><span class="status-pill open">Feedback open</span><button class="small-btn" data-feedback-course="${c.id}">Review →</button></div>`).join('')}</div>`:empty('No open feedback requests','There are no enrolled courses awaiting a response right now.')}</section>`}
else{const scores=allFeedback.flatMap(f=>[f.teaching_quality,f.course_content,f.engagement,f.assessment]);body=`<div class="welcome-strip"><div><span class="eyebrow">ACADEMIC QUALITY</span><h2>Welcome, ${esc(state.profile.full_name||'colleague')}</h2><p>Insights here are calculated from current database submissions, not sample records.</p></div><div class="welcome-mark">e</div></div><div class="stats-grid">${stat('Courses',state.courses.length,'Available course records','▣')}${stat('Feedback received',allFeedback.length,'Stored submissions','✎')}${stat('Average rating',fmt(avg(scores)),scores.length?'Across four rating criteria':'No ratings recorded yet','☆')}</div><section class="panel"><div class="panel-head"><div><h2>Recently updated courses</h2><p>Current records from the institutional database.</p></div><button class="text-btn" data-page="courses">Browse courses →</button></div>${state.courses.length?`<div class="course-list">${state.courses.slice(0,5).map(c=>`<div class="course-row"><div class="course-badge">${esc(c.code.slice(0,2))}</div><div class="course-info"><strong>${esc(c.title)}</strong><span>${esc(c.code)} · ${esc(c.department||'Department not set')}</span></div><span class="status-pill ${c.is_published?'published':'draft'}">${c.is_published?'Published':'Draft'}</span></div>`).join('')}</div>`:empty('No courses have been added','An administrator can create and publish course records from Portal management.')}</section>`}
if(state.announcements.length)body+=`<section class="panel"><div class="panel-head"><div><h2>Institution announcements</h2><p>Published messages for your account.</p></div></div>${state.announcements.filter(a=>a.audience==='all'||a.audience===role).map(a=>`<div class="announcement"><strong>${esc(a.title)}</strong><p>${esc(a.body)}</p><small>${date(a.created_at)}</small></div>`).join('')}</section>`;return `${heading(isAdmin?'Administrator overview':role==='student'?'Your learning feedback':'Faculty overview','A live view of your portal, based on records your account is allowed to access.')} ${body}`}
async function coursesPage(){let list=state.courses.filter(c=>c.is_published||state.profile.role==='admin'||c.faculty_id===state.user.id);if(state.profile.role==='student'){const {data,error}=await supabase.from('enrollments').select('course_id').eq('student_id',state.user.id);if(error)throw error;const ids=new Set((data||[]).map(x=>x.course_id));list=list.filter(c=>ids.has(c.id))}return `${heading('Courses','Browse the course records available to your account.',state.profile.role==='admin'?'<button class="primary-btn" data-action="new-course">+ Add course</button>':'')}<section class="panel"><div class="table-toolbar"><div><h2>Course directory</h2><p>${list.length} accessible course record${list.length===1?'':'s'}</p></div><input class="search-input" id="courseSearch" placeholder="Search code, title, department…" aria-label="Search courses"></div><div class="table-wrap"><table><thead><tr><th>Course</th><th>Department</th><th>Faculty</th><th>Term</th><th>Status</th>${state.profile.role==='student'?'<th>Feedback</th>':''}</tr></thead><tbody id="courseRows">${list.map(c=>`<tr data-search="${esc((c.code+' '+c.title+' '+c.department).toLowerCase())}"><td><strong>${esc(c.title)}</strong><small>${esc(c.code)}</small></td><td>${esc(c.department||'—')}</td><td>${esc(c.faculty?.full_name||'Not assigned')}</td><td>${esc(c.term||'—')}</td><td><span class="status-pill ${c.is_published?'published':'draft'}">${c.is_published?'Published':'Draft'}</span></td>${state.profile.role==='student'?`<td>${c.feedback_open?`<button class="small-btn" data-feedback-course="${c.id}">Give feedback</button>`:'<span class="muted">Closed</span>'}`:''}</tr>`).join('')}</tbody></table></div>${!list.length?empty('No course records yet','Your account has no accessible courses. Ask the portal administrator if this seems incorrect.') : ''}</section>`}
async function feedbackFormPage(){const {data:enrs,error}=await supabase.from('enrollments').select('course_id,courses(id,title,code,feedback_open,is_published)').eq('student_id',state.user.id);if(error)throw error;const {data:sent,error:se}=await supabase.from('feedback').select('course_id').eq('student_id',state.user.id);if(se)throw se;const done=new Set((sent||[]).map(f=>f.course_id));const options=(enrs||[]).map(e=>e.courses).filter(c=>c&&c.is_published&&c.feedback_open&&!done.has(c.id));return `${heading('Submit feedback','Share specific, constructive feedback about a course. Your submission is stored in the institutional database.')}<div class="form-layout"><section class="panel form-panel">${options.length?`<form id="feedbackForm"><label for="feedbackCourse">Course</label><select id="feedbackCourse" required><option value="">Select a course</option>${options.map(c=>`<option value="${c.id}" ${state.filters.course===c.id?'selected':''}>${esc(c.code)} — ${esc(c.title)}</option>`).join('')}</select><div class="rating-block"><label>Teaching quality</label><div class="rating-control" data-rating="teaching_quality">${[1,2,3,4,5].map(n=>`<button type="button" data-score="${n}" aria-label="${n} out of 5">☆</button>`).join('')}</div><small>Clarity, preparation, and explanation</small></div><div class="rating-block"><label>Course content</label><div class="rating-control" data-rating="course_content">${[1,2,3,4,5].map(n=>`<button type="button" data-score="${n}" aria-label="${n} out of 5">☆</button>`).join('')}</div><small>Structure, relevance, and learning materials</small></div><div class="rating-block"><label>Engagement</label><div class="rating-control" data-rating="engagement">${[1,2,3,4,5].map(n=>`<button type="button" data-score="${n}" aria-label="${n} out of 5">☆</button>`).join('')}</div><small>Interaction, participation, and support</small></div><div class="rating-block"><label>Assessment & workload</label><div class="rating-control" data-rating="assessment">${[1,2,3,4,5].map(n=>`<button type="button" data-score="${n}" aria-label="${n} out of 5">☆</button>`).join('')}</div><small>Fairness, workload, and assessment alignment</small></div><label for="feedbackComments">Comments <span class="optional">(optional)</span></label><textarea id="feedbackComments" rows="5" maxlength="3000" placeholder="What worked well? What could be improved?"></textarea><label class="check-line"><input id="anonymousCheck" type="checkbox" ${state.settings?.allow_anonymous?'checked':''} ${state.settings?.allow_anonymous?'':'disabled'}><span>Hide my identity from faculty viewers where supported</span></label><p class="privacy-note">Your account is used to prevent duplicate submissions. Database administrators can still access the underlying record.</p><button class="primary-btn" type="submit">Submit feedback <span>→</span></button></form>`:empty('No feedback forms available','A published course must be assigned to you and have its feedback window opened by an administrator.')} </section><aside class="guidance-card"><span class="guidance-icon">✳</span><h3>Make it constructive.</h3><p>${esc(state.settings?.feedback_guidelines||'Please keep feedback constructive, respectful, and specific.')}</p><div class="guidance-rule"></div><strong>A useful response is</strong><ul><li>Specific and respectful</li><li>Focused on learning outcomes</li><li>Balanced and actionable</li></ul></aside></div>`}
async function myFeedbackPage(){const {data,error}=await supabase.from('feedback').select('*,courses(title,code)').eq('student_id',state.user.id).order('created_at',{ascending:false});if(error)throw error;return `${heading('My submissions','Your feedback history is private to your account.')}<section class="panel"><div class="panel-head"><div><h2>Submission history</h2><p>${(data||[]).length} saved submission${(data||[]).length===1?'':'s'}</p></div><button class="secondary-btn" data-action="export-my-feedback">Export CSV</button></div>${data?.length?`<div class="table-wrap"><table><thead><tr><th>Course</th><th>Submitted</th><th>Average</th><th>Status</th><th></th></tr></thead><tbody>${data.map(f=>`<tr><td><strong>${esc(f.courses?.title||'Course')}</strong><small>${esc(f.courses?.code||'')}</small></td><td>${date(f.created_at)}</td><td>${fmt(avg([f.teaching_quality,f.course_content,f.engagement,f.assessment]))} / 5</td><td><span class="status-pill published">${esc(f.status)}</span></td><td><button class="small-btn" data-view-feedback="${f.id}">View</button></td></tr>`).join('')}</tbody></table></div>`:empty('No submissions yet','Your submitted course evaluations will appear here.')}</section>`}
async function facultyPage(){const {data,error}=await supabase.from('feedback').select('id,course_id,teaching_quality,course_content,engagement,assessment,comments,status,created_at,courses!inner(title,code,faculty_id)').eq('courses.faculty_id',state.user.id).order('created_at',{ascending:false});if(error)throw error;const rows=data||[];const ratings=rows.flatMap(f=>[f.teaching_quality,f.course_content,f.engagement,f.assessment]);return `${heading('Faculty insights','Feedback associated with courses assigned to your faculty account.')}<div class="stats-grid">${stat('Responses',rows.length,'Assigned courses only','✎')}${stat('Average rating',fmt(avg(ratings)),ratings.length?'Across rating criteria':'No ratings yet','☆')}${stat('Courses',new Set(rows.map(f=>f.course_id)).size,'Courses with responses','▣')}</div><section class="panel"><div class="panel-head"><div><h2>Recent feedback</h2><p>Student identities are not shown in this view.</p></div></div>${rows.length?`<div class="feedback-cards">${rows.slice(0,30).map(f=>`<article class="feedback-card"><div class="feedback-card-top"><div><strong>${esc(f.courses?.title||'Course')}</strong><small>${esc(f.courses?.code||'')} · ${date(f.created_at)}</small></div><span class="rating-chip">☆ ${fmt(avg([f.teaching_quality,f.course_content,f.engagement,f.assessment]))}</span></div><div class="mini-ratings">${[['Teaching',f.teaching_quality],['Content',f.course_content],['Engagement',f.engagement],['Assessment',f.assessment]].map(([k,v])=>`<span>${k}<b>${v}/5</b></span>`).join('')}</div><p>${esc(f.comments||'No written comment provided.')}</p></article>`).join('')}</div>`:empty('No feedback available yet','Responses appear after students submit evaluations for courses assigned to you.')}</section>`}
async function analyticsPage(){const isAdmin=state.profile.role==='admin';let q=supabase.from('feedback').select('id,course_id,teaching_quality,course_content,engagement,assessment,created_at');if(state.profile.role==='faculty'){const ids=state.courses.filter(c=>c.faculty_id===state.user.id).map(c=>c.id);q=q.in('course_id',ids.length?ids:['00000000-0000-0000-0000-000000000000'])}const {data,error}=await q.order('created_at',{ascending:false});if(error)throw error;const rows=data||[],scores=rows.flatMap(f=>[f.teaching_quality,f.course_content,f.engagement,f.assessment]);const counts=[1,2,3,4,5].map(n=>rows.reduce((acc,f)=>acc+[f.teaching_quality,f.course_content,f.engagement,f.assessment].filter(x=>x===n).length,0));const max=Math.max(1,...counts);const courseRows=state.courses.filter(c=>isAdmin||c.faculty_id===state.user.id).map(c=>{const fs=rows.filter(f=>f.course_id===c.id);return {...c,n:fs.length,score:avg(fs.flatMap(f=>[f.teaching_quality,f.course_content,f.engagement,f.assessment]))}}).sort((a,b)=>(b.score||0)-(a.score||0));return `${heading('Analytics & insights','Aggregated directly from stored feedback. No fabricated metrics are displayed.',isAdmin?'<button class="secondary-btn" data-action="export-analytics">Export CSV</button>':'')}<div class="stats-grid">${stat('Total responses',rows.length,'Database submissions','✎')}${stat('Overall average',fmt(avg(scores)),scores.length?'Across all criteria':'No ratings yet','☆')}${stat('Courses evaluated',new Set(rows.map(f=>f.course_id)).size,'With at least one response','▣')}</div><div class="analytics-grid"><section class="panel"><div class="panel-head"><div><h2>Rating distribution</h2><p>Number of criterion ratings at each score.</p></div></div>${counts.every(n=>n===0)?empty('Not enough data yet','Rating distribution will appear after the first evaluation.'):counts.map((n,i)=>`<div class="bar-row"><span>${i+1} star${i?'s':''}</span><div class="bar-track"><div class="bar-fill" style="width:${n/max*100}%"></div></div><strong>${n}</strong></div>`).join('')}</section><section class="panel"><div class="panel-head"><div><h2>Criterion averages</h2><p>Mean score from available responses.</p></div></div>${[['Teaching quality','teaching_quality'],['Course content','course_content'],['Engagement','engagement'],['Assessment','assessment']].map(([label,key])=>{const n=avg(rows.map(f=>f[key]));return `<div class="criterion-row"><span>${label}</span><strong>${fmt(n)} <small>/ 5</small></strong></div>`}).join('')}</section></div><section class="panel"><div class="panel-head"><div><h2>Course comparison</h2><p>Courses are shown only where your access permits.</p></div></div>${courseRows.length?`<div class="table-wrap"><table><thead><tr><th>Course</th><th>Responses</th><th>Average criterion score</th></tr></thead><tbody>${courseRows.map(c=>`<tr><td><strong>${esc(c.title)}</strong><small>${esc(c.code)}</small></td><td>${c.n}</td><td>${fmt(c.score)}${c.score!=null?' / 5':''}</td></tr>`).join('')}</tbody></table></div>`:empty('No courses to compare','Course comparisons appear when course records and feedback exist.')}</section>`}
async function managePage(){const [people,feedback,logs]=await Promise.all([supabase.from('profiles').select('id',{count:'exact',head:true}),supabase.from('feedback').select('id',{count:'exact',head:true}),supabase.from('audit_logs').select('id,action,entity_type,created_at,profiles(full_name,email)').order('created_at',{ascending:false}).limit(8)]);if(people.error)throw people.error;if(feedback.error)throw feedback.error;return `${heading('Portal management','Control the live course directory, feedback windows, announcements, and institutional activity.','<button class="secondary-btn" data-action="manage-enrollments">Manage enrollments</button><button class="primary-btn" data-action="new-course">+ Add course</button>')}<div class="stats-grid">${stat('People',people.count??'—','Accounts with profiles','♧')}${stat('Course records',state.courses.length,'Draft and published','▣')}${stat('Submissions',feedback.count??'—','Real feedback records','✎')}</div><div class="admin-grid"><section class="panel"><div class="panel-head"><div><h2>Course administration</h2><p>Create, publish, assign, and open or close feedback.</p></div><button class="text-btn" data-page="courses">Full directory →</button></div>${state.courses.length?`<div class="admin-course-list">${state.courses.map(c=>`<div class="admin-course-row"><div class="course-badge">${esc(c.code.slice(0,2))}</div><div class="course-info"><strong>${esc(c.title)}</strong><span>${esc(c.code)} · ${esc(c.term||'No term')}</span><small>${esc(c.faculty?.full_name||'Faculty unassigned')}</small></div><div class="admin-course-actions"><span class="status-pill ${c.is_published?'published':'draft'}">${c.is_published?'Published':'Draft'}</span><button class="icon-action" title="Edit course" data-edit-course="${c.id}">✎</button><button class="icon-action" title="Toggle publication" data-toggle-publish="${c.id}">${c.is_published?'◉':'○'}</button><button class="icon-action" title="Toggle feedback" data-toggle-feedback="${c.id}">${c.feedback_open?'▣':'▢'}</button></div></div>`).join('')}</div>`:empty('Your course catalogue is empty','Create a course record to begin. Nothing has been preloaded.')}<p class="panel-footnote">Publishing makes a course visible to enrolled students. Feedback can be submitted only while its window is open.</p></section><section class="panel"><div class="panel-head"><div><h2>Announcements</h2><p>Publish notices to role-specific audiences.</p></div><button class="secondary-btn" data-action="new-announcement">+ New</button></div>${state.announcements.length?state.announcements.map(a=>`<div class="announcement"><div class="announcement-head"><strong>${esc(a.title)}</strong><span class="status-pill published">Published</span></div><p>${esc(a.body)}</p><small>${esc(a.audience)} · ${date(a.created_at)}</small><button class="text-btn danger-text" data-delete-announcement="${a.id}">Delete</button></div>`).join(''):empty('No published announcements','Create a notice when there is something to share.')}</section></div><section class="panel"><div class="panel-head"><div><h2>Recent audit activity</h2><p>Recent tracked management actions.</p></div><button class="text-btn" data-page="people">Manage people →</button></div>${logs.data?.length?`<div class="table-wrap"><table><thead><tr><th>Action</th><th>Record</th><th>Actor</th><th>Date</th></tr></thead><tbody>${logs.data.map(l=>`<tr><td><strong>${esc(l.action)}</strong></td><td>${esc(l.entity_type)}</td><td>${esc(l.profiles?.full_name||l.profiles?.email||'Account')}</td><td>${date(l.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No audit activity yet','Management actions will be recorded as they occur.')}</section>`}
async function peoplePage(){const {data,error}=await supabase.from('profiles').select('id,full_name,email,role,department,student_number,is_active,created_at').order('created_at',{ascending:false});if(error)throw error;state.people=data||[];return `${heading('People & access','Create institutional accounts, review registered users, and manage portal roles. Account creation uses a protected Supabase Edge Function.','<button class="primary-btn" data-action="new-user">+ Create account</button>')}<section class="panel"><div class="table-toolbar"><div><h2>Registered accounts</h2><p>${state.people.length} profile record${state.people.length===1?'':'s'}</p></div><input id="peopleSearch" class="search-input" placeholder="Search name, email, role…" aria-label="Search people"><button class="secondary-btn" data-action="export-people">Export CSV</button></div><div class="notice"><strong>Security note</strong><p>Role and active-status changes apply immediately. Only grant administrator access to trusted institutional staff. This browser never receives a Supabase service-role key.</p></div><div class="table-wrap"><table><thead><tr><th>Person</th><th>Role</th><th>Department</th><th>Status</th><th>Access controls</th></tr></thead><tbody id="peopleRows">${state.people.map(p=>`<tr data-search="${esc((p.full_name+' '+p.email+' '+p.role+' '+(p.department||'')).toLowerCase())}"><td><strong>${esc(p.full_name||'Name not set')}</strong><small>${esc(p.email)}</small></td><td><select class="table-select" data-person-role="${p.id}" ${p.id===state.user.id?'disabled title="You cannot change your own role here"':''}>${['student','faculty','admin'].map(r=>`<option value="${r}" ${p.role===r?'selected':''}>${r}</option>`).join('')}</select></td><td>${esc(p.department||'—')}</td><td><span class="status-pill ${p.is_active?'published':'draft'}">${p.is_active?'Active':'Disabled'}</span></td><td><button class="small-btn ${p.is_active?'danger-btn':''}" data-toggle-person="${p.id}" ${p.id===state.user.id?'disabled':''}>${p.is_active?'Disable':'Enable'}</button></td></tr>`).join('')}</tbody></table></div>${state.people.length?'':empty('No registered profiles','When accounts are created through Supabase Auth, their profiles will appear here.')}</section>`}
async function settingsPage(){const s=state.settings||{};return `${heading('Portal settings','Configure the public-facing institutional text and feedback policy. Changes are stored in the database.')}<section class="panel settings-panel"><form id="settingsForm"><div class="form-section-title"><h2>Institution identity</h2><p>These details are used throughout the authenticated portal.</p></div><div class="form-grid"><div><label for="institutionName">Institution name</label><input id="institutionName" value="${esc(s.institution_name||'')}" required maxlength="140"></div><div><label for="portalTitle">Portal title</label><input id="portalTitle" value="${esc(s.portal_title||'')}" required maxlength="160"></div></div><label for="welcomeMessage">Welcome message</label><textarea id="welcomeMessage" rows="3" maxlength="500">${esc(s.welcome_message||'')}</textarea><label for="feedbackGuidelines">Feedback guidelines</label><textarea id="feedbackGuidelines" rows="4" maxlength="2000">${esc(s.feedback_guidelines||'')}</textarea><div class="form-section-title"><h2>Feedback controls</h2><p>Changes affect subsequent feedback forms.</p></div><label class="setting-toggle"><span><strong>Allow anonymous display</strong><small>Hide student identity from faculty views. Administrators can still access underlying records.</small></span><input type="checkbox" id="allowAnonymous" ${s.allow_anonymous?'checked':''}></label><label class="setting-toggle"><span><strong>Maintenance mode</strong><small>Display a maintenance notice to users. This is a portal setting, not a substitute for deployment-level access controls.</small></span><input type="checkbox" id="maintenanceMode" ${s.maintenance_mode?'checked':''}></label><button class="primary-btn" type="submit">Save portal settings <span>→</span></button></form></section>`}
function bindPageActions(){ $$('#pageContent [data-page]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.page)));$$('#pageContent [data-feedback-course]').forEach(b=>b.addEventListener('click',()=>{state.filters.course=b.dataset.feedbackCourse;navigate('give-feedback')}));const search=$('#courseSearch');if(search)search.addEventListener('input',()=>$$('#courseRows tr').forEach(tr=>tr.hidden=!tr.dataset.search.includes(search.value.toLowerCase())));const ps=$('#peopleSearch');if(ps)ps.addEventListener('input',()=>$$('#peopleRows tr').forEach(tr=>tr.hidden=!tr.dataset.search.includes(ps.value.toLowerCase())));
$$('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));$$('[data-edit-course]').forEach(b=>b.addEventListener('click',()=>courseModal(state.courses.find(c=>c.id===b.dataset.editCourse))));$$('[data-toggle-publish]').forEach(b=>b.addEventListener('click',()=>updateCourseFlag(b.dataset.togglePublish,'is_published')));$$('[data-toggle-feedback]').forEach(b=>b.addEventListener('click',()=>updateCourseFlag(b.dataset.toggleFeedback,'feedback_open')));$$('[data-delete-announcement]').forEach(b=>b.addEventListener('click',()=>deleteAnnouncement(b.dataset.deleteAnnouncement)));$$('[data-toggle-person]').forEach(b=>b.addEventListener('click',()=>togglePerson(b.dataset.togglePerson)));$$('[data-person-role]').forEach(s=>s.addEventListener('change',()=>changeRole(s.dataset.personRole,s.value)));$$('[data-view-feedback]').forEach(b=>b.addEventListener('click',()=>viewFeedback(b.dataset.viewFeedback)));const ff=$('#feedbackForm');if(ff){const scores={};$$('.rating-control button',ff).forEach(b=>b.addEventListener('click',()=>{const group=b.closest('.rating-control'),key=group.dataset.rating;scores[key]=Number(b.dataset.score);$$('button',group).forEach(x=>{x.classList.toggle('selected',Number(x.dataset.score)<=scores[key]);x.textContent=Number(x.dataset.score)<=scores[key]?'★':'☆'})}));ff.addEventListener('submit',async e=>{e.preventDefault();const keys=['teaching_quality','course_content','engagement','assessment'];if(keys.some(k=>!scores[k])){fail('Please rate all four criteria before submitting.');return}const course=$('#feedbackCourse').value;if(!course){fail('Select a course first.');return}const {error}=await supabase.from('feedback').insert({course_id:course,student_id:state.user.id,...Object.fromEntries(keys.map(k=>[k,scores[k]])),comments:$('#feedbackComments').value.trim(),is_anonymous:$('#anonymousCheck').checked});if(error){fail(error.code==='23505'?'You have already submitted feedback for this course.':error.message);return}await logAction('submitted_feedback','feedback',null,{course_id:course});toast('Feedback submitted successfully.');state.filters.course=null;navigate('my-feedback')})}const sf=$('#settingsForm');if(sf)sf.addEventListener('submit',saveSettings)}
async function action(name){if(name==='retry')return renderPage();if(name==='new-course')return courseModal();if(name==='new-user')return userModal();if(name==='new-announcement')return announcementModal();if(name==='manage-enrollments')return enrollmentsModal();if(name==='export-analytics')return exportAnalytics();if(name==='export-people')return exportPeople();if(name==='export-my-feedback')return exportMyFeedback()}
function modal(title,body){$('#modalRoot').innerHTML=`<div class="modal-backdrop" id="modalBackdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><div><span class="eyebrow accent">EVALORA ADMIN</span><h2 id="modalTitle">${title}</h2></div><button class="icon-action" id="closeModal" aria-label="Close">×</button></div>${body}</section></div>`;$('#closeModal').onclick=()=>$('#modalRoot').innerHTML='';$('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')$('#modalRoot').innerHTML=''})}
async function courseModal(c=null){const {data:faculty,error}=await supabase.from('profiles').select('id,full_name,email').eq('role','faculty').eq('is_active',true).order('full_name');if(error)return fail(error.message);modal(c?'Edit course':'Create a course',`<form id="courseForm" class="modal-form"><label>Course code</label><input id="courseCode" required maxlength="30" value="${esc(c?.code||'')}" placeholder="e.g. CSE326"><label>Course title</label><input id="courseName" required maxlength="180" value="${esc(c?.title||'')}" placeholder="Course title"><div class="form-grid"><div><label>Department</label><input id="courseDepartment" required maxlength="120" value="${esc(c?.department||'')}" placeholder="Department"></div><div><label>Academic term</label><input id="courseTerm" maxlength="100" value="${esc(c?.term||'')}" placeholder="e.g. Fall 2026"></div></div><label>Assigned faculty</label><select id="courseFaculty"><option value="">Unassigned</option>${faculty.map(p=>`<option value="${p.id}" ${c?.faculty_id===p.id?'selected':''}>${esc(p.full_name||p.email)} — ${esc(p.email)}</option>`).join('')}</select><label>Description</label><textarea id="courseDescription" rows="3" maxlength="1500">${esc(c?.description||'')}</textarea><label class="check-line"><input type="checkbox" id="coursePublished" ${c?.is_published?'checked':''}><span>Publish course to enrolled students</span></label><label class="check-line"><input type="checkbox" id="courseFeedbackOpen" ${c?.feedback_open?'checked':''}><span>Open feedback window</span></label><div class="modal-actions"><button type="button" class="secondary-btn" id="cancelModal">Cancel</button><button class="primary-btn" type="submit">${c?'Save changes':'Create course'}</button></div></form>`);$('#cancelModal').onclick=()=>$('#modalRoot').innerHTML='';$('#courseForm').onsubmit=async e=>{e.preventDefault();const values={code:$('#courseCode').value.trim().toUpperCase(),title:$('#courseName').value.trim(),department:$('#courseDepartment').value.trim(),term:$('#courseTerm').value.trim(),faculty_id:$('#courseFaculty').value||null,description:$('#courseDescription').value.trim(),is_published:$('#coursePublished').checked,feedback_open:$('#courseFeedbackOpen').checked,updated_at:new Date().toISOString()};const req=c?supabase.from('courses').update(values).eq('id',c.id):supabase.from('courses').insert(values);const {data,error}=await req.select().single();if(error)return fail(error.message);await logAction(c?'updated_course':'created_course','course',data.id,{code:data.code});$('#modalRoot').innerHTML='';toast(c?'Course updated':'Course created');renderPage()}}


function userModal(){
 modal('Create institutional account',`<form id="userForm" class="modal-form"><p class="muted">Creates a real Supabase Auth account and matching portal profile. Share the temporary password securely and ask the user to change it after sign-in.</p><label>Full name</label><input id="newUserName" required maxlength="140" autocomplete="off"><label>University email</label><input id="newUserEmail" type="email" required maxlength="254" autocomplete="off"><div class="form-grid"><div><label>Role</label><select id="newUserRole"><option value="student">Student</option><option value="faculty">Faculty</option><option value="admin">Administrator</option></select></div><div><label>Department</label><input id="newUserDepartment" maxlength="120"></div></div><label>Temporary password</label><input id="newUserPassword" type="password" minlength="12" required autocomplete="new-password" placeholder="At least 12 characters"><p class="privacy-note">The temporary password is sent only to the protected Edge Function and is not saved in portal records or audit logs.</p><div class="modal-actions"><button type="button" class="secondary-btn" id="cancelModal">Cancel</button><button class="primary-btn" type="submit">Create account</button></div></form>`);
 $('#cancelModal').onclick=()=>$('#modalRoot').innerHTML='';
 $('#userForm').onsubmit=async e=>{e.preventDefault();const button=$('#userForm button[type=submit]');button.disabled=true;button.textContent='Creating account…';const payload={full_name:$('#newUserName').value.trim(),email:$('#newUserEmail').value.trim(),role:$('#newUserRole').value,department:$('#newUserDepartment').value.trim(),password:$('#newUserPassword').value};const {data,error}=await supabase.functions.invoke('admin-create-user',{body:payload});button.disabled=false;button.textContent='Create account';if(error)return fail(data?.error||error.message||'Account creation failed. Confirm the Edge Function is deployed.');if(data?.error)return fail(data.error);$('#modalRoot').innerHTML='';toast(`Account created for ${data.email}`);renderPage()};
}

async function enrollmentsModal(){
 const [students,courses,enrollments]=await Promise.all([
  supabase.from('profiles').select('id,full_name,email').eq('role','student').eq('is_active',true).order('full_name'),
  supabase.from('courses').select('id,title,code').order('code'),
  supabase.from('enrollments').select('id,student_id,course_id,created_at,profiles(full_name,email),courses(title,code)').order('created_at',{ascending:false}).limit(200)
 ]);
 for(const r of [students,courses,enrollments])if(r.error)return fail(r.error.message);
 modal('Manage course enrollments',`<form id="enrollmentForm" class="modal-form"><p class="muted">Assign an existing student account to an existing course. Only actual database records are shown.</p><label>Student account</label><select id="enrollStudent" required><option value="">Select student</option>${(students.data||[]).map(p=>`<option value="${p.id}">${esc(p.full_name||p.email)} — ${esc(p.email)}</option>`).join('')}</select><label>Course</label><select id="enrollCourse" required><option value="">Select course</option>${(courses.data||[]).map(c=>`<option value="${c.id}">${esc(c.code)} — ${esc(c.title)}</option>`).join('')}</select><div class="modal-actions"><button type="button" class="secondary-btn" id="cancelModal">Close</button><button class="primary-btn" type="submit">Create enrollment</button></div></form><div class="form-section-title"><h2>Current enrollments</h2><p>Up to 200 most recent enrollment records.</p></div><div class="table-wrap enrollment-table"><table><thead><tr><th>Student</th><th>Course</th><th></th></tr></thead><tbody>${(enrollments.data||[]).map(e=>`<tr><td><strong>${esc(e.profiles?.full_name||e.profiles?.email||'Student')}</strong><small>${esc(e.profiles?.email||'')}</small></td><td><strong>${esc(e.courses?.title||'Course')}</strong><small>${esc(e.courses?.code||'')}</small></td><td><button class="small-btn danger-btn" data-remove-enrollment="${e.id}">Remove</button></td></tr>`).join('')}</tbody></table></div>${(enrollments.data||[]).length?'':'<p class="muted">No enrollment records exist yet.</p>'}`);
 $('#cancelModal').onclick=()=>$('#modalRoot').innerHTML='';
 $('#enrollmentForm').onsubmit=async e=>{e.preventDefault();const student_id=$('#enrollStudent').value,course_id=$('#enrollCourse').value;const {data,error}=await supabase.from('enrollments').insert({student_id,course_id}).select().single();if(error)return fail(error.code==='23505'?'That student is already enrolled in this course.':error.message);await logAction('created_enrollment','enrollment',data.id,{student_id,course_id});toast('Student enrolled successfully');enrollmentsModal()};
 $$('[data-remove-enrollment]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Remove this student from the course?'))return;const {error}=await supabase.from('enrollments').delete().eq('id',b.dataset.removeEnrollment);if(error)return fail(error.message);await logAction('removed_enrollment','enrollment',b.dataset.removeEnrollment);toast('Enrollment removed');enrollmentsModal()}));
}

async function updateCourseFlag(id,key){const c=state.courses.find(x=>x.id===id);if(!c)return;const {error}=await supabase.from('courses').update({[key]:!c[key],updated_at:new Date().toISOString()}).eq('id',id);if(error)return fail(error.message);await logAction(`changed_${key}`,'course',id,{value:!c[key]});toast('Course settings updated');renderPage()}
function announcementModal(){modal('New announcement',`<form id="announcementForm" class="modal-form"><label>Title</label><input id="announcementTitle" required maxlength="180"><label>Message</label><textarea id="announcementBody" rows="5" required maxlength="4000"></textarea><label>Audience</label><select id="announcementAudience"><option value="all">Everyone</option><option value="student">Students</option><option value="faculty">Faculty</option><option value="admin">Administrators</option></select><label class="check-line"><input type="checkbox" id="announcementPublished" checked><span>Publish immediately</span></label><div class="modal-actions"><button type="button" class="secondary-btn" id="cancelModal">Cancel</button><button class="primary-btn" type="submit">Save announcement</button></div></form>`);$('#cancelModal').onclick=()=>$('#modalRoot').innerHTML='';$('#announcementForm').onsubmit=async e=>{e.preventDefault();const {data,error}=await supabase.from('announcements').insert({title:$('#announcementTitle').value.trim(),body:$('#announcementBody').value.trim(),audience:$('#announcementAudience').value,is_published:$('#announcementPublished').checked,created_by:state.user.id}).select().single();if(error)return fail(error.message);await logAction('created_announcement','announcement',data.id);$('#modalRoot').innerHTML='';toast('Announcement saved');renderPage()}}
async function deleteAnnouncement(id){if(!confirm('Delete this announcement? This cannot be undone.'))return;const {error}=await supabase.from('announcements').delete().eq('id',id);if(error)return fail(error.message);await logAction('deleted_announcement','announcement',id);toast('Announcement deleted');renderPage()}
async function togglePerson(id){const p=state.people.find(x=>x.id===id);if(!p||p.id===state.user.id)return;if(!confirm(`${p.is_active?'Disable':'Enable'} access for ${p.email}?`))return;const {error}=await supabase.from('profiles').update({is_active:!p.is_active,updated_at:new Date().toISOString()}).eq('id',id);if(error)return fail(error.message);await logAction(p.is_active?'disabled_account':'enabled_account','profile',id);toast('Account status updated');renderPage()}
async function changeRole(id,role){const p=state.people.find(x=>x.id===id);if(!p||id===state.user.id)return;const {error}=await supabase.from('profiles').update({role,updated_at:new Date().toISOString()}).eq('id',id);if(error){fail(error.message);renderPage();return}await logAction('changed_role','profile',id,{from:p.role,to:role});toast('Account role updated');renderPage()}
async function saveSettings(e){e.preventDefault();const values={id:true,institution_name:$('#institutionName').value.trim(),portal_title:$('#portalTitle').value.trim(),welcome_message:$('#welcomeMessage').value.trim(),feedback_guidelines:$('#feedbackGuidelines').value.trim(),allow_anonymous:$('#allowAnonymous').checked,maintenance_mode:$('#maintenanceMode').checked,updated_at:new Date().toISOString(),updated_by:state.user.id};const {error}=await supabase.from('portal_settings').upsert(values,{onConflict:'id'});if(error)return fail(error.message);await logAction('updated_portal_settings','portal_settings',null,{institution_name:values.institution_name});toast('Portal settings saved');await renderPage()}
async function viewFeedback(id){const {data,error}=await supabase.from('feedback').select('*,courses(title,code)').eq('id',id).single();if(error)return fail(error.message);modal('Submission details',`<div class="detail-list"><div><span>Course</span><strong>${esc(data.courses?.title||'Course')}</strong></div><div><span>Submitted</span><strong>${date(data.created_at)}</strong></div><div><span>Teaching quality</span><strong>${data.teaching_quality}/5</strong></div><div><span>Course content</span><strong>${data.course_content}/5</strong></div><div><span>Engagement</span><strong>${data.engagement}/5</strong></div><div><span>Assessment</span><strong>${data.assessment}/5</strong></div><div><span>Average</span><strong>${fmt(avg([data.teaching_quality,data.course_content,data.engagement,data.assessment]))}/5</strong></div></div><label>Comments</label><p class="detail-comment">${esc(data.comments||'No written comment provided.')}</p><div class="modal-actions"><button class="primary-btn" id="closeDetail">Close</button></div>`);$('#closeDetail').onclick=()=>$('#modalRoot').innerHTML=''}
function csvDownload(name, rows){if(!rows.length)return toast('There is no data to export yet.','error');const csv=rows.map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url)}
async function exportAnalytics(){const {data,error}=await supabase.from('feedback').select('created_at,course_id,teaching_quality,course_content,engagement,assessment,status');if(error)return fail(error.message);csvDownload('evalora-feedback-analytics.csv',[['Submitted at','Course ID','Teaching quality','Course content','Engagement','Assessment','Status'],...(data||[]).map(f=>[f.created_at,f.course_id,f.teaching_quality,f.course_content,f.engagement,f.assessment,f.status])])}
function exportPeople(){csvDownload('evalora-people.csv',[['Name','Email','Role','Department','Active','Created'],...state.people.map(p=>[p.full_name,p.email,p.role,p.department,p.is_active,p.created_at])])}
async function exportMyFeedback(){const {data,error}=await supabase.from('feedback').select('created_at,course_id,teaching_quality,course_content,engagement,assessment,comments,status').eq('student_id',state.user.id);if(error)return fail(error.message);csvDownload('my-evalora-feedback.csv',[['Submitted at','Course ID','Teaching quality','Course content','Engagement','Assessment','Comments','Status'],...(data||[]).map(f=>[f.created_at,f.course_id,f.teaching_quality,f.course_content,f.engagement,f.assessment,f.comments,f.status])])}
async function signIn(e){e.preventDefault();if(!requireClient())return;const email=$('#loginEmail').value.trim(),password=$('#loginPassword').value;const btn=$('#loginForm button[type=submit]');btn.disabled=true;btn.textContent='Signing in…';setMessage('');try{const {data,error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error;await loadProfile(data.user);await logAction('signed_in','auth_user',data.user.id);showApp();await navigate('dashboard')}catch(err){setMessage(err.message==='Invalid login credentials'?'Email or password is incorrect.':err.message||'Unable to sign in.');}finally{btn.disabled=false;btn.innerHTML='Sign in <span>→</span>'}}
async function signOut(){if(supabase)await supabase.auth.signOut();state.user=null;state.profile=null;showLogin()}
async function start(){ $('#yearNow').textContent=new Date().getFullYear();$('#loginForm').addEventListener('submit',signIn);$('#togglePassword').addEventListener('click',()=>{$('#loginPassword').type=$('#loginPassword').type==='password'?'text':'password'});$('#logoutBtn').addEventListener('click',signOut);$('#dropdownLogout').addEventListener('click',signOut);$('#profileMenuBtn').addEventListener('click',()=>$('#profileDropdown').classList.toggle('hidden'));$('#menuToggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$$('.nav-item[data-page]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.page)));if(!configured){$('#loginMessage').textContent='Setup required: configure config.js and run schema.sql in your Supabase project.';$('#connectionLabel').textContent='Setup needed';$$('.connection-status').forEach(el=>el.classList.add('offline'));return}const {data:{session}}=await supabase.auth.getSession();if(session){try{await loadProfile(session.user);showApp();await navigate('dashboard')}catch(e){await supabase.auth.signOut();showLogin();setMessage(e.message)}}supabase.auth.onAuthStateChange(async(event,session)=>{if(event==='SIGNED_OUT'){showLogin()}else if(event==='SIGNED_IN'&&session&&!state.profile){try{await loadProfile(session.user);showApp();await navigate('dashboard')}catch(e){fail(e.message)}}})}
start();
